import * as T from './vendor/three.module.js';
const V=(x,y,z)=>new T.Vector3(x,y,z);
let seed=119;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
function shellTexture(){const c=document.createElement('canvas');c.width=c.height=512;const ctx=c.getContext('2d');ctx.fillStyle='#403429';ctx.fillRect(0,0,512,512);for(let i=0;i<22000;i++){const x=rnd()*512,y=rnd()*512,d=Math.abs(x-256)/256,stripe=Math.sin(y*.042)*Math.sin(d*8);ctx.fillStyle=`rgba(${stripe>.1?'184,160,115':'18,15,12'},${.1+rnd()*.4})`;ctx.fillRect(x,y,1+rnd()*3,1+rnd()*4);}const map=new T.CanvasTexture(c);map.colorSpace=T.SRGBColorSpace;return map;}
const shell=new T.MeshStandardMaterial({color:'#aaa28d',map:shellTexture(),roughness:.64,metalness:.08});
const joint=new T.MeshStandardMaterial({color:'#211b17',roughness:.42});const eye=new T.MeshPhysicalMaterial({color:'#090908',roughness:.08,clearcoat:1});
function body(group,p,scale,material){const mesh=new T.Mesh(new T.SphereGeometry(1,32,24),material);mesh.position.copy(p);mesh.scale.set(...scale);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return mesh;}
function fur(group,coords,color='#65503b'){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(coords,3));const lines=new T.LineSegments(geo,new T.LineBasicMaterial({color,transparent:true,opacity:.72}));group.add(lines);return lines;}
function bodyHair(g,center,scale,count){const pts=[];for(let i=0;i<count;i++){const a=rnd()*Math.PI*2,z=rnd()*2-1,r=Math.sqrt(1-z*z),n=V(Math.cos(a)*r,z,Math.sin(a)*r);if(n.y<-.25)continue;const p=n.clone().multiply(V(...scale)).add(center),end=p.clone().addScaledVector(n,.015+rnd()*.035);end.z+=.012;pts.push(...p,...end)}fur(g,pts);}
function segment(g,points,r1,r2){const curve=new T.CatmullRomCurve3(points),geo=new T.TubeGeometry(curve,12,1,8,false),p=geo.attributes.position;for(let i=0;i<p.count;i++){const t=Math.floor(i/9)/12,center=curve.getPointAt(t);const r=r1+(r2-r1)*t;const v=V(p.getX(i),p.getY(i),p.getZ(i)).sub(center).multiplyScalar(r).add(center);p.setXYZ(i,...v);}geo.computeVertexNormals();const mesh=new T.Mesh(geo,shell);mesh.castShadow=true;g.add(mesh);const hairs=[];for(let i=0;i<130;i++){const t=rnd(),a=rnd()*Math.PI*2,p=curve.getPointAt(t),n=V(Math.cos(a),Math.sin(a),rnd()*.25).normalize();p.addScaledVector(n,r1+(r2-r1)*t);hairs.push(...p,...p.clone().addScaledVector(n,(.018+rnd()*.045)*(g.userData.view?.16:1)));}fur(g,hairs);}
export function createSpider(size=1){const g=new T.Group(),limbs=[];g.scale.setScalar(size);
 body(g,V(0,.19,.18),[.19,.16,.27],shell);bodyHair(g,V(0,.19,.18),[.19,.16,.27],1400);
 body(g,V(0,.17,-.16),[.16,.115,.17],shell);bodyHair(g,V(0,.17,-.16),[.16,.115,.17],700);
 for(let s of [-1,1]){for(let i=0;i<4;i++){const leg=new T.Group();g.add(leg);const z=-.25+i*.135,kz=(i-1.5)*.27,k=V(s*(.4+Math.sin(i)*.04),.23,kz),tip=V(s*(.61+Math.sin(i)*.09),.014,(i-1.5)*.43);segment(leg,[V(s*.105,.17,z),V(s*.26,.21,z),k],.035,.021);body(leg,k,[.03,.028,.034],joint);segment(leg,[k,k.clone().lerp(tip,.55).add(V(0,.012,0)),tip],.021,.004);limbs.push(leg);}
 for(let i=0;i<4;i++){const r=i===0?.023:.013;body(g,V(s*(.034+i*.025),.21+(i===0?.025:0),-.307+i*.01),[r,r,r],eye)}
 segment(g,[V(s*.065,.15,-.26),V(s*.13,.095,-.38),V(s*.095,.07,-.44)],.026,.012);
 }
 g.userData.animate=(t,moving=false)=>{limbs.forEach((leg,i)=>{const a=moving?.11:.018;leg.rotation.y=Math.sin(t*(moving?11:1.6)+i*2.4)*a;leg.rotation.z=Math.max(0,Math.sin(t*(moving?11:1.6)+i*2.4))*a*.5*(i<4?1:-1)});};return g;}
export function createViewLegs(camera){const g=new T.Group();camera.add(g);for(let s of [-1,1])for(let i=0;i<4;i++){const leg=new T.Group();g.add(leg);leg.userData.view=true;const start=V(s*(.19+i*.02),-.24-i*.02,-.08),knee=V(s*(.34+i*.08),-.12-i*.048,-.37-i*.06),tip=V(s*(.32+i*.12),-.29-i*.035,-.72+i*.055);segment(leg,[start,start.clone().lerp(knee,.5).add(V(0,.025,0)),knee],.021,.015);body(leg,knee,[.02,.02,.028],joint);segment(leg,[knee,knee.clone().lerp(tip,.55),tip],.015,.0025);}return g;}
